bool UNullableElementsLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FNullableElements::ReadAll(BasePath, FileExtension);
}

bool FNullableElements::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FListingTable LoadedListing;

    if (!LoadedListing.Read(FPaths::Combine(BasePath, TEXT("Listing") + FileExtension)))
    {
        return false;
    }
    FFoldedTable LoadedFolded;

    if (!LoadedFolded.Read(FPaths::Combine(BasePath, TEXT("Folded") + FileExtension)))
    {
        return false;
    }

    ListingStorage = MoveTemp(LoadedListing);
    FoldedStorage = MoveTemp(LoadedFolded);

    return true;
}
